import { ChartEvent, ActiveElement } from 'chart.js';

import full from 'url:../assets/full.jpg';
import long from 'url:../assets/long.jpg';
import short from 'url:../assets/short.jpg';
import stache from 'url:../assets/stache.jpg';

export const labelImagesSources = [stache, short, full, long];

export const chartConfig = {
  velo: {
    legendXMin: 94,
    title: '2026 Average Fastball Velocity',
  },
  breaking: {
    // legendXMin: 0,
    title: '2026 Average Breaking Ball/Offspeed Velocity',
  },
  gameScore: {
    legendXMin: 50,
    title: '2026 Game Scores',
  },
  k9: {
    legendXMin: 9,
    title: '2026 Strikeouts/9',
  },
};

export const chartOptions = (
  titleText: string,
  loadedImages: never[],
  showLegend: boolean = true,
  xMin: number = 0
) => ({
  responsive: true,
  onHover: (event: ChartEvent, chartElements: ActiveElement[]) => {
    const target = event.native?.target as HTMLElement | null;
    if (target) {
      target.style.cursor = chartElements.length > 0 ? 'pointer' : 'default';
    }
  },
  maintainAspectRatio: false,
  indexAxis: 'y' as const,
  layout: {
    padding: {
      left: 50,
    },
  },
  scales: {
    x: {
      beginAtZero: false,
      min: xMin ? xMin : undefined,
      grace: '3%' as const,
    },
    y: {
      grid: {
        drawOnChartArea: false,
      },
      ticks: {
        // Distance between the Y-axis baseline border and the text strings
        padding: 8,
        display: false,
      },
    },
  },
  plugins: {
    legend: {
      display: showLegend,
      position: 'top' as const,
      onHover: (event: ChartEvent) => {
        const target = event.native?.target as HTMLElement | null;
        if (target) {
          target.style.cursor = 'pointer';
        }
      },
      onLeave: (event: ChartEvent) => {
        const target = event.native?.target as HTMLElement | null;
        if (target) {
          target.style.cursor = 'default';
        }
      },
    },
    title: {
      display: true,
      text: titleText,
    },
    yAxisImageLabels: {
      images: loadedImages,
    },
  },
});
